def find_rational_points(max_q):
    solutions = []
    for q in range(1, max_q + 1):
        for p in range(-2 * q, 10 * q):
            if p == 0:
                continue
            num = p**3 + 4*p**2*q + 3*p*q**2 - 2*q**3
            den = q**3
            val = num * den
            if val >= 0:
                root = int(val**0.5)
                if root * root == val:
                    # Check if p/q is actually a solution (p/q is z)
                    # Note: num * den = (p^3 + 4p^2q + 3pq^2 - 2q^3) * q^3
                    # We need (p^3 + 4p^2q + 3pq^2 - 2q^3) / q^3 to be a square.
                    # That's the same as num * q being a square if q is a square.
                    # Wait, let's just re-calculate:
                    z = p / q
                    w_sq = z**3 + 4*z**2 + 3*z - 2
                    if w_sq >= 0:
                        w = w_sq**0.5
                        if abs(w - round(w)) < 1e-9:
                            solutions.append((p, q))
    return solutions

print(find_rational_points(100))

